insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-matematica-basica','Matemática básica','Números, operações e proporcionalidade','400','RLM — Matemática básica: números, frações, porcentagem e proporções','Números reais, operações, MDC/MMC, frações, razões, proporções, regra de três, porcentagem, medidas e expressões numéricas.','## Conteúdo da trilha

Esta trilha reúne **Números Reais**, operações com frações, potenciação e radiciação, expressões numéricas, MDC e MMC, razões e proporções, regra de três, porcentagem, sistema de medidas e unidades de tempo.

### Método de estudo

1. Resolva primeiro parênteses, colchetes e chaves; depois potências e raízes; em seguida multiplicações e divisões; por fim adições e subtrações.
2. Em frações, reduza ao mesmo denominador para somar ou subtrair; na multiplicação, multiplique numeradores e denominadores; na divisão, multiplique pela fração inversa.
3. Em razão e proporção, preserve a ordem das grandezas. Regra de três direta mantém o sentido; na inversa, uma grandeza cresce enquanto a outra diminui.
4. Em porcentagem, transforme p% em p/100. Aumentos sucessivos multiplicam fatores: (1+a)(1+b), não somam percentuais.
5. No sistema métrico, cada salto de unidade vale fator 10; em área, fator 100; em volume, fator 1000.

> **Cai em prova:** diferença entre porcentagem do valor inicial e pontos percentuais; conversão de unidades; MMC para sincronização de eventos; MDC para divisão em grupos iguais.','Concurso público — RLM','400','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Números Reais.pdf, Operações com Frações.pdf, Potenciação e Radiciacao.pdf, Expressões numéricas.pdf, MDC e MMC.pdf, Razões e proporções.pdf, Regra de Tres.pdf, Porcentagem.pdf, Sistema de medidas.pdf, Unidades de Tempo.pdf.','[{"title": "PDF enviado pelo usuário — Números Reais.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Operações com Frações.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Potenciação e Radiciacao.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Expressões numéricas.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — MDC e MMC.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Razões e proporções.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Regra de Tres.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Porcentagem.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Sistema de medidas.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Unidades de Tempo.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Números reais, operações, MDC/MMC, frações, razões, proporções, regra de três, porcentagem, medidas e expressões numéricas."}]'::jsonb,'[{"q": "O material Números Reais.pdf deve ser estudado dentro de Números, operações e proporcionalidade.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-algebra-funcoes','Raciocínio Lógico','Álgebra e funções','401','RLM — Álgebra e funções: equações, inequações e gráficos','Equações e inequações do primeiro grau, funções constante e quadrática e leitura de gráficos.','## Conteúdo da trilha

Inclui equação do 1º grau, inequação do 1º grau, função constante, funções e função do 2º grau.

### Equações e inequações

Isole a incógnita aplicando operações equivalentes nos dois membros. Ao multiplicar ou dividir uma inequação por número negativo, inverta o sinal. Registre o conjunto solução e confira no enunciado.

### Funções

Uma função associa cada entrada a uma única saída. Na função afim, f(x)=ax+b: a é a inclinação e b é o intercepto. Na função constante, a=0. Na função quadrática, f(x)=ax²+bx+c; o vértice tem x_v=-b/(2a), e o discriminante Δ=b²-4ac informa o número de raízes reais.

> **Cai em prova:** interpretar o sinal de a, o vértice e as raízes no gráfico; distinguir domínio, contradomínio e imagem.','Concurso público — RLM','401','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Equacao do 1 grau.pdf, Inequacoes 1 grau.pdf, Função constante.pdf, Funções.pdf, Função do 2 grau.pdf.','[{"title": "PDF enviado pelo usuário — Equacao do 1 grau.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Inequacoes 1 grau.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Função constante.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Funções.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Função do 2 grau.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Equações e inequações do primeiro grau, funções constante e quadrática e leitura de gráficos."}]'::jsonb,'[{"q": "O material Equacao do 1 grau.pdf deve ser estudado dentro de Álgebra e funções.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-sequencias-progressoes','Raciocínio Lógico','Sequências e progressões','402','RLM — Sequências numéricas, PA e PG','Padrões, sequências lógicas, progressão aritmética e progressão geométrica.','## Conteúdo da trilha

Antes de aplicar fórmula, compare diferenças, razões, alternâncias e posições. Em sequências lógicas, procure repetição de blocos, alternância, soma de termos anteriores e padrões de posição.

### Progressão aritmética

A diferença é constante: a_n=a_1+(n-1)r. A soma dos n primeiros termos é S_n=n(a_1+a_n)/2.

### Progressão geométrica

A razão é constante: a_n=a_1 q^(n-1). Para q≠1, S_n=a_1(q^n-1)/(q-1). Em PG infinita com |q|<1, S=a_1/(1-q).

> **Cai em prova:** não confundir diferença constante com razão constante; testar termos iniciais e a posição pedida.','Concurso público — RLM','402','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Sequência lógica.pdf, Sequências numéricas.pdf, Progressão Aritmética.pdf, Progressão geométrica.pdf.','[{"title": "PDF enviado pelo usuário — Sequência lógica.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Sequências numéricas.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Progressão Aritmética.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Progressão geométrica.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Padrões, sequências lógicas, progressão aritmética e progressão geométrica."}]'::jsonb,'[{"q": "O material Sequência lógica.pdf deve ser estudado dentro de Sequências e progressões.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-matrizes-determinantes-sistemas','Raciocínio Lógico','Matrizes, determinantes e sistemas','403','RLM — Matrizes, determinantes e sistemas lineares','Operações matriciais, determinantes, propriedades, escalonamento, regra de Cramer e sistemas lineares.','## Conteúdo da trilha

Matriz é uma tabela organizada por linhas e colunas. Some matrizes de mesma ordem; no produto AB, o número de colunas de A deve ser igual ao número de linhas de B.

### Determinantes

Para ordem 2, det[[a,b],[c,d]]=ad-bc. Em ordem 3, use Sarrus ou cofatores. Trocar duas linhas muda o sinal; multiplicar uma linha por k multiplica o determinante por k; linha proporcional ou nula torna o determinante zero.

### Sistemas lineares

Classifique pelo escalonamento: uma linha 0=0 é compatível com liberdade; uma linha 0=c, c≠0, é incompatível; pivô em todas as incógnitas indica solução única. A regra de Cramer aplica-se quando o determinante principal é diferente de zero.

> **Cai em prova:** ordem do produto, interpretação do determinante nulo e classificação do sistema.','Concurso público — RLM','403','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Matrizes.pdf, Matrizes operações.pdf, Determinantes.pdf, Determinantes propriedades.pdf, Sistemas Lineares.pdf.','[{"title": "PDF enviado pelo usuário — Matrizes.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Matrizes operações.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Determinantes.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Determinantes propriedades.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Sistemas Lineares.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Operações matriciais, determinantes, propriedades, escalonamento, regra de Cramer e sistemas lineares."}]'::jsonb,'[{"q": "O material Matrizes.pdf deve ser estudado dentro de Matrizes, determinantes e sistemas.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-geometria-trigonometria','Raciocínio Lógico','Geometria e trigonometria','404','RLM — Geometria plana, espacial e trigonometria','Áreas, perímetros, volumes, pontos notáveis, relações métricas e trigonometria.','## Conteúdo da trilha

### Geometria plana

Revise triângulos, quadriláteros, circunferência e polígonos. Área do triângulo: base vezes altura dividido por 2; círculo: πr²; comprimento da circunferência: 2πr.

### Pontos notáveis

O baricentro é o encontro das medianas; o incentro, das bissetrizes; o circuncentro, das mediatrizes; o ortocentro, das alturas. Relacione cada ponto à reta que o define.

### Geometria espacial

Prisma e cilindro: área da base vezes altura para volume. Pirâmide e cone: um terço da área da base vezes altura. Esfera: V=4πr³/3 e A=4πr².

### Trigonometria

No triângulo retângulo, sen=cateto oposto/hipotenusa, cos=cateto adjacente/hipotenusa e tg=oposto/adjacente. Converta graus e radianos por 180°=π rad.

> **Cai em prova:** unidade de área/volume, semelhança, Pitágoras, relações seno/cosseno e conversão angular.','Concurso público — RLM','404','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Geometria plana.pdf, Geometria Espacial.pdf, Pontos notáveis triângulo.pdf, Trigonometria.pdf, Trigonometria continuação.pdf.','[{"title": "PDF enviado pelo usuário — Geometria plana.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Geometria Espacial.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Pontos notáveis triângulo.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Trigonometria.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Trigonometria continuação.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Áreas, perímetros, volumes, pontos notáveis, relações métricas e trigonometria."}]'::jsonb,'[{"q": "O material Geometria plana.pdf deve ser estudado dentro de Geometria e trigonometria.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-combinatoria-probabilidade','Raciocínio Lógico','Análise combinatória e probabilidade','405','RLM — Análise combinatória e probabilidade','Princípio multiplicativo, permutações, arranjos, combinações, eventos, probabilidade condicional e casos especiais.','## Conteúdo da trilha

Use o princípio multiplicativo quando a escolha ocorre em etapas. Permutação simples: n!. Arranjo de n elementos tomados p a p: A(n,p)=n!/(n-p)!. Combinação: C(n,p)=n!/[p!(n-p)!].

Em probabilidade, P(A)=casos favoráveis/casos possíveis em espaço equiprovável. Complementar: P(A^c)=1-P(A). União: P(A∪B)=P(A)+P(B)-P(A∩B). Condicional: P(A|B)=P(A∩B)/P(B). Se independentes, P(A∩B)=P(A)P(B).

> **Cai em prova:** ordem importa em arranjo e não importa em combinação; em probabilidade condicional, o espaço amostral muda.','Concurso público — RLM','405','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Análise combinatória.pdf, Análise combinatória Arranjos.pdf, Análise combinatória casos especiais.pdf, Probabilidade.pdf, Probabilidade casos especiais.pdf.','[{"title": "PDF enviado pelo usuário — Análise combinatória.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Análise combinatória Arranjos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Análise combinatória casos especiais.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Probabilidade.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Probabilidade casos especiais.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Princípio multiplicativo, permutações, arranjos, combinações, eventos, probabilidade condicional e casos especiais."}]'::jsonb,'[{"q": "O material Análise combinatória.pdf deve ser estudado dentro de Análise combinatória e probabilidade.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-logica-proposicional','Raciocínio Lógico','Lógica proposicional','406','RLM — Proposições, tabelas-verdade, equivalências e tautologias','Proposições simples e compostas, conectivos, negações, equivalências, leis de De Morgan e tautologia.','## Conteúdo da trilha

Proposição é uma frase declarativa que pode ser verdadeira ou falsa. Negação inverte o valor lógico. Na conjunção p∧q, ambas devem ser verdadeiras; na disjunção p∨q, pelo menos uma; no condicional p→q, só é falso quando p é verdadeira e q é falsa; na bicondicional p↔q, os valores coincidem.

### Equivalências essenciais

p→q equivale a ¬p∨q e também a ¬q→¬p. A negação de p∧q é ¬p∨¬q; a negação de p∨q é ¬p∧¬q. Tautologia é sempre verdadeira; contradição, sempre falsa; contingência varia.

Use tabela-verdade para validar equivalências e identificar tautologias. Em n proposições simples, a tabela possui 2^n linhas.

> **Cai em prova:** negar o condicional corretamente; distinguir recíproca, inversa e contrapositiva; aplicar De Morgan.','Concurso público — RLM','406','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Proposições.pdf, Proposições a1.pdf, Proposições  Resumo.pdf, Equivalência logica.pdf, Tautologia.pdf.','[{"title": "PDF enviado pelo usuário — Proposições.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Proposições a1.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Proposições  Resumo.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Equivalência logica.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Tautologia.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Proposições simples e compostas, conectivos, negações, equivalências, leis de De Morgan e tautologia."}]'::jsonb,'[{"q": "O material Proposições.pdf deve ser estudado dentro de Lógica proposicional.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('rlm-acervo-argumentacao-associacao','Raciocínio Lógico','Argumentação e associações','407','RLM — Argumentos, correlações, verdades e mentiras','Validade de argumentos, métodos de classificação, associação lógica e problemas de verdades e mentiras.','## Conteúdo da trilha

Argumento é um conjunto de premissas que pretende sustentar uma conclusão. Validade depende da estrutura: um argumento é válido quando não existe situação com premissas verdadeiras e conclusão falsa.

### Métodos

Use tabela-verdade para argumentos pequenos; método das premissas verdadeiras para buscar contraexemplo; método da conclusão falsa para verificar se as premissas podem permanecer verdadeiras. Um contraexemplo basta para invalidar.

### Associação e verdades/mentiras

Monte tabela de pessoas, atributos, posições e restrições. Marque certezas, elimine incompatibilidades e só depois use as pistas condicionais. Em problemas de verdades e mentiras, teste as hipóteses mantendo coerência global.

> **Cai em prova:** validade não depende de as premissas serem factualmente verdadeiras; depende da impossibilidade de premissas verdadeiras com conclusão falsa.','Concurso público — RLM','407','Conteúdo consolidado a partir dos PDFs enviados pelo usuário em 28/10/2026: Argumento.pdf, Métodos de argumentação.pdf, Métodos para classificar argumentos.pdf, Métodos para classificar argumentos cont.pdf, Associação Lógica.pdf, Correlacionamentos.pdf, Verdades e mentiras.pdf.','[{"title": "PDF enviado pelo usuário — Argumento.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Métodos de argumentação.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Métodos para classificar argumentos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Métodos para classificar argumentos cont.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Associação Lógica.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Correlacionamentos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "PDF enviado pelo usuário — Verdades e mentiras.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]'::jsonb,'[{"f": "Qual é o foco desta trilha?", "b": "Validade de argumentos, métodos de classificação, associação lógica e problemas de verdades e mentiras."}]'::jsonb,'[{"q": "O material Argumento.pdf deve ser estudado dentro de Argumentação e associações.", "a": true, "why": "A trilha foi organizada a partir do acervo enviado."}]'::jsonb,'active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
commit;